#mainpopup {
  z-index: 100000;
  position: fixed;
  left: 0;
  top: 0;
  display: flex;
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  font-family: "TTNorms-Regular";
  width: 100%;
  height: 100%;
  background: rgba(1, 22, 39, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}
