.popups-auth .progress {
  font: 12px Arial, Tahoma, sans-serif;
  position: relative;
  overflow: hidden;
  width: 100%;
}
.popups-auth .progress progress {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  left: -777px;
}
.popups-auth .progress .progress-value {
  color: white;
  display: block;
  line-height: 21px;
  text-align: center;
}
.popups-auth .progress .progress-bg {
  background: #e6e9ed;
  position: relative;
  height: 8px;
  border-radius: 5px;
  overflow: hidden;
}
@keyframes progress_bar {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: -40px 0;
  }
}
.popups-auth .progress .progress-bar {
  overflow: hidden;
  background: #D33437;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  transition: width 1s linear;
}
.popups-auth .progress .progress-bar:after {
  animation: progress_bar 0.8s linear infinite;
  background-image: linear-gradient(45deg, rgba(255, 255, 255, 0.15) 25%, transparent 25%, transparent 50%, rgba(255, 255, 255, 0.15) 50%, rgba(255, 255, 255, 0.15) 75%, transparent 75%, transparent);
  background-size: 40px 40px;
  position: absolute;
  content: "";
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.popups-auth .box-auth {
  background: rgba(27, 30, 40, 0.9);
  height: -moz-fit-content;
  height: fit-content;
  transition: max-height 0.7s;
  position: relative;
  display: flex;
  align-items: center;
  flex-direction: column;
  color: white;
}
@media (max-width: 799px) {
  .popups-auth .box-auth {
    border-radius: 2.7px;
  }
}
@media (min-width: 800px) and (max-width: 999px) {
  .popups-auth .box-auth {
    border-radius: 3px;
  }
