@font-face {
  font-family: "houseicon";
  src: url(../src/views/house/buymenu/fonts//houseicon.eot);
  src: url(../src/views/house/buymenu/fonts//houseicon.eot#iefix) format("embedded-opentype"), url(../src/views/house/buymenu/fonts//houseicon.ttf) format("truetype"), url(../src/views/house/buymenu/fonts//houseicon.woff) format("woff"), url(/src/views/house/buymenu/fonts/houseicon.svg#houseicon) format("svg");
  font-weight: normal;
  font-style: normal;
  font-display: block;
}
[class^=houseicon-], [class*=" houseicon-"] {
  /* use !important to prevent issues with browser extensions that change fonts */
  font-family: "houseicon" !important;
  speak: never;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  /* Better Font Rendering =========== */
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

